// Compact SHA-256 (FIPS 180-4) — for WAF Proof-of-Work challenge
var SHA256=(function(){
var K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
function R(x,n){return(x>>>n)|(x<<(32-n));}
return function(s){
var m=[];for(var i=0;i<s.length;i++){var c=s.charCodeAt(i);if(c<128)m.push(c);else if(c<2048){m.push(192+(c>>6),128+(c&63));}else{m.push(224+(c>>12),128+((c>>6)&63),128+(c&63));}}
var l=m.length,b=l*8;m.push(0x80);while((m.length%64)!=56)m.push(0);
for(var i=7;i>=0;i--)m.push((b>>>((7-i)*8))&0xff);
var H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
for(var off=0;off<m.length;off+=64){
var W=[];for(var j=0;j<16;j++)W[j]=(m[off+j*4]<<24)|(m[off+j*4+1]<<16)|(m[off+j*4+2]<<8)|m[off+j*4+3];
for(var j=16;j<64;j++){var s0=R(W[j-15],7)^R(W[j-15],18)^(W[j-15]>>>3);var s1=R(W[j-2],17)^R(W[j-2],19)^(W[j-2]>>>10);W[j]=(W[j-16]+s0+W[j-7]+s1)|0;}
var a=H[0],b2=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
for(var j=0;j<64;j++){
var S1=R(e,6)^R(e,11)^R(e,25);var ch=(e&f)^(~e&g);var t1=(h+S1+ch+K[j]+W[j])|0;
var S0=R(a,2)^R(a,13)^R(a,22);var maj=(a&b2)^(a&c)^(b2&c);var t2=(S0+maj)|0;
h=g;g=f;f=e;e=(d+t1)|0;d=c;c=b2;b2=a;a=(t1+t2)|0;}
H[0]=(H[0]+a)|0;H[1]=(H[1]+b2)|0;H[2]=(H[2]+c)|0;H[3]=(H[3]+d)|0;
H[4]=(H[4]+e)|0;H[5]=(H[5]+f)|0;H[6]=(H[6]+g)|0;H[7]=(H[7]+h)|0;}
return H.map(function(x){return('00000000'+(x>>>0).toString(16)).slice(-8);}).join('');
};
})();

// countLeadingZeroBits: count leading zero bits in a hex hash string
function clzb(hex){var n=0;for(var i=0;i<hex.length;i++){var c=parseInt(hex[i],16);if(c===0){n+=4;continue;}if(c<2)n+=3;else if(c<4)n+=2;else if(c<8)n+=1;break;}return n;}

// solvePow: find nonce so SHA256(challenge+':'+nonce) has >=bits leading zero bits
// chunked via setTimeout to avoid blocking UI; calls cb(nonce) when found
function solvePow(challenge,bits,cb){
var nonce=0;
(function chunk(){
var end=nonce+50000;
while(nonce<end){
var h=SHA256(challenge+':'+nonce);
if(clzb(h)>=bits){cb(nonce);return;}
nonce++;
}
setTimeout(chunk,0);
})();
}
